	// swallowed. That is exactly where a refusal lands (Y on an empty listing
	// has nothing to copy), and a refusal nobody can read is worse than none.
	return theme.EmptyLineBg(width) + "\n" + m.renderInfoLine(width)
}

// renderInfoLine is the footer's one line of state.
//
// A sync's progress is read from the run rather than from footerInfo because a
// batch outlives the three seconds a footer message gets: a line set when the
// first repository started would clear while the tenth was still fetching. An
// error still wins over it — it is the thing that needs answering.
func (m Model) renderInfoLine(width int) string {
	return m.footer.View(width, m.status())
}

// status is the derived footer line: the selected row's own sentence (what it
// is doing, or the failure it remembers), then the batch progress. A row with a
// running or queued detail has a dot that already moves, so the footer spinner is dropped.
func (m Model) status() sharedcomponents.Status {
	st := sharedcomponents.Status{Text: m.jobsStatusLine()}
	moving := false
	if row, ok := m.table.Selected(); ok {
		a := m.rowActivity(row.Entry)
		st.Detail = a.Detail
		moving = a.State == indicator.Running || a.State == indicator.Queued
	}
	// Only a detail whose dot moves replaces the spinner; a failed row's is fixed.
	st.Spinner = m.anyWorking() && (!moving || st.Detail.IsZero())
	return st
}

// renderTabBar renders the breadcrumb tab bar at the bottom of the viewport
func (m Model) renderTabBar() string {
	tabs := []theme.TabItem{{Label: theme.IconHome + " home"}}

	// Add navigation stack entries as tabs
// View renders the footer's line of text, always at the full width and always
// centred — including when it is empty, because Rule 124 budgets a line for it
// whatever it holds.
//
// Precedence: error, warning, info, then the derived status. A failure the user
// has not read yet matters more than the progress of what is still running.
func (f *FooterMessage) View(width int, status Status) string {
	if width <= 0 {
		return ""
	}

	// A timed message wins over the derived status: a failure the user has not
	// read yet matters more than the progress of what is still running.
	//
	// Truncation is not cosmetic — a line wider than the viewport wraps onto a
	// second one, and the router budgeted exactly one (Rule 124). Everything
	// below it would shift by a line.
	if f.text != "" {
		return centerLine(f.level.Style().Render(theme.TruncateWidth(f.text, width)), width)
	}
	if status.Text == "" && status.Detail.IsZero() {
